WHO = {'bridge': [('norlllellyvi', 111124), ('psiloceyeben', 111379), ('solkllgepy', 111571), ('mulwei', 111571), ('eindfeldmicr', 112402), ('mulwei', 0), ('norlllellyvi', 112785), ('dukklewei', 0)], 'tree': [('qufollellyvi', 111124), ('zeashel', 0), ('dukklkize', 0), ('aprilfools', 111315), ('dukkllgepy', 0), ('eindlsof', 0), ('dukklkize', 112530), ('dukkllledum', 114256)], 'temple': [('aprilanor', 0), ('renvi', 0), ('qum', 113360), ('norlllelefya', 114000), ('dukklkize', 117837), ('qum', 0), ('norlllelefya', 125513)], 'column': [('renvi', 111188), ('muut', 111315), ('eindfellben', 0), ('mulwei', 0), ('maeefllben', 111379), ('maeefelor', 111443), ('alphafoldmicro', 0), ('norlllllllut', 111891)], 'tower': [('eindfellyvi', 0), ('maeeflgepy', 113041), ('solkllben', 115214), ('dukkllgepy', 116109), ('dukkllgepy', 0), ('loorfellyvi', 0), ('maeelwei', 0), ('eindfellben', 121420)], 'inscription': [('mulwei', 114703), ('mulwei', 0)], 'manor': [('dukklkize', 116365), ('solkeellyvi', 119885)], 'castle': [('loorfellyvi', 118093), ('renvi', 119245), ('ashllelefya', 120461)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW18(OracleReleaseRuntimeW16):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
